EXPORT ZZT_APPCOLL() BEGIN
LOCAL R,E,W,V:=[1,2],O:={};
HComplex:=1; L1:={1,2};
A:=0; E:=0; W:=-1; R:=-99;
IFERR R:=append(V,3); R(1):=9; THEN E:=1; END;
IF E==0 THEN IFERR W:=TYPE(R(3)); THEN W:=-2; END; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R),W,STRING(SIZE(R)),STRING(V),STRING(L1)}});
A:=0; E:=0; W:=-1; R:=-99;
IFERR R:=append(L1,[3,4]); R(1):=9; THEN E:=1; END;
IF E==0 THEN IFERR W:=TYPE(R(3)); THEN W:=-2; END; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R),W,STRING(SIZE(R)),STRING(V),STRING(L1)}});
A:=0; E:=0; W:=-1; R:=-99;
IFERR R:=append(ZZT_TICK(1,V),ZZT_TICK(2,3));  THEN E:=1; END;
IF E==0 THEN IFERR W:=TYPE(R(3)); THEN W:=-2; END; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R),W,STRING(SIZE(R)),STRING(V),STRING(L1)}});
A:=0; E:=0; W:=-1; R:=-99;
IFERR R:=append(ZZT_FAIL(1),ZZT_TICK(2,3));  THEN E:=1; END;
IF E==0 THEN IFERR W:=TYPE(R(3)); THEN W:=-2; END; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R),W,STRING(SIZE(R)),STRING(V),STRING(L1)}});
A:=0; E:=0; W:=-1; R:=-99;
IFERR R:=append(ZZT_TICK(1,V),ZZT_FAIL(2));  THEN E:=1; END;
IF E==0 THEN IFERR W:=TYPE(R(3)); THEN W:=-2; END; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R),W,STRING(SIZE(R)),STRING(V),STRING(L1)}});
RETURN O; END;
ZZT_TICK(D,T) BEGIN A:=A*10+D; RETURN T; END;
ZZT_FAIL(D) BEGIN A:=A*10+D; RETURN 1/0; END;
